CREATE TABLE execution_graph_revisions (
  execution_id TEXT NOT NULL REFERENCES workflow_executions (id),
  revision INTEGER NOT NULL CHECK (revision >= 1),
  graph TEXT NOT NULL CHECK (json_valid(graph)),
  cause TEXT NOT NULL CHECK (cause IN ('materialized', 'patch')),
  patch_id TEXT REFERENCES graph_patches (id),
  created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  PRIMARY KEY (execution_id, revision),
  CHECK ((cause = 'patch') = (patch_id IS NOT NULL))
) STRICT;

CREATE TABLE nodes (
  id TEXT PRIMARY KEY NOT NULL CHECK (substr(id, 1, 5) = 'node_' AND length(id) = 37 AND substr(id, 6) NOT GLOB '*[^0-9a-f]*'),
  execution_id TEXT NOT NULL REFERENCES workflow_executions (id),
  node_key TEXT NOT NULL,
  iteration INTEGER NOT NULL DEFAULT 0 CHECK (iteration >= 0),
  type TEXT NOT NULL CHECK (type IN ('deterministic_action', 'agent', 'integration', 'human_decision', 'condition', 'bounded_map', 'join', 'verification', 'compensation', 'subworkflow', 'bounded_loop')),
  added_in_revision INTEGER NOT NULL CHECK (added_in_revision >= 1),
  config TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(config)),
  state TEXT NOT NULL CHECK (state IN ('pending', 'ready', 'running', 'succeeded', 'failed', 'skipped', 'cancelled', 'uncertain')),
  created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  UNIQUE (execution_id, node_key, iteration)
) STRICT;

CREATE INDEX tasks_by_project ON tasks (project_id, state);

CREATE INDEX task_plans_by_task ON task_plans (task_id);

CREATE INDEX runs_by_task ON runs (task_id);

CREATE INDEX workspace_sets_by_run_attempt ON workspace_sets (run_attempt_id);

