CREATE TABLE threads (
  id TEXT PRIMARY KEY NOT NULL CHECK (substr(id, 1, 4) = 'thr_' AND length(id) = 36 AND substr(id, 5) NOT GLOB '*[^0-9a-f]*'),
  project_id TEXT NOT NULL REFERENCES projects (id),
  kind TEXT NOT NULL CHECK (kind IN ('coordinator', 'task', 'step')),
  owner_actor_id TEXT REFERENCES actors (id),
  task_id TEXT REFERENCES tasks (id),
  node_id TEXT REFERENCES nodes (id),
  created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  CHECK (
    (kind = 'coordinator' AND owner_actor_id IS NOT NULL AND task_id IS NULL AND node_id IS NULL)
    OR (kind = 'task' AND owner_actor_id IS NULL AND task_id IS NOT NULL AND node_id IS NULL)
    OR (kind = 'step' AND owner_actor_id IS NULL AND task_id IS NOT NULL AND node_id IS NOT NULL)
  )
) STRICT;

CREATE TABLE user_inputs (
  id TEXT PRIMARY KEY NOT NULL CHECK (substr(id, 1, 6) = 'input_' AND length(id) = 38 AND substr(id, 7) NOT GLOB '*[^0-9a-f]*'),
  thread_id TEXT NOT NULL REFERENCES threads (id),
  sequence INTEGER NOT NULL CHECK (sequence >= 1),
  command_id TEXT NOT NULL UNIQUE CHECK (substr(command_id, 1, 4) = 'cmd_'),
  disposition TEXT NOT NULL CHECK (disposition IN ('after_current', 'interrupt_and_continue', 'supersede_pending', 'cancel_run')),
  body TEXT NOT NULL,
  author_actor_id TEXT NOT NULL REFERENCES actors (id),
  state TEXT NOT NULL CHECK (state IN ('queued', 'delivered', 'superseded')),
  accepted_at TEXT NOT NULL CHECK (accepted_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
  UNIQUE (thread_id, sequence)
) STRICT;

CREATE TABLE turn_deliveries (
  id TEXT PRIMARY KEY NOT NULL CHECK (substr(id, 1, 5) = 'turn_' AND length(id) = 37 AND substr(id, 6) NOT GLOB '*[^0-9a-f]*'),
